create function pg_temp.deny(q text, label text) returns void language plpgsql as $$begin begin execute q;exception when others then if sqlerrm like 'JADWAL:%' or sqlstate='42501' then return;end if;raise;end;raise exception 'FAIL: % accepted',label;end$$;
