create function pg_temp.new_swap() returns uuid language sql security definer as $$
 select (public.hris_request_schedule_swap(a.id,a.updated_at,b.id,b.updated_at,'91000000-0000-0000-0000-000000000001','Fiction repeatable scenario')).id from employee_schedules a,employee_schedules b where a.id='95000000-0000-0000-0000-000000000001' and b.id='95000000-0000-0000-0000-000000000002'
$$;
