create temp table before_swap as select to_jsonb(s) row from employee_schedules s;
create temp table before_events as select count(*)n from schedule_swap_events;
create function pg_temp.break_second_write() returns trigger language plpgsql as $$begin if new.id='95000000-0000-0000-0000-000000000002' then raise exception 'JADWAL: Fiction injected second write failure';end if;return new;end$$;
create trigger break_swap before update on employee_schedules for each row execute function pg_temp.break_second_write();
set local role authenticated;
select set_config('request.jwt.claim.sub','90000000-0000-0000-0000-000000000002',true);
select pg_temp.deny(format('select hris_decide_schedule_swap(%L,true,%L)',(select id from schedule_swap_requests where status='Menunggu HR'),'Fiction second write'),'second write failure');
reset role;
select pg_temp.check_it(not exists(select to_jsonb(s) from employee_schedules s except select row from before_swap),'both cells rollback after second write fails');
select pg_temp.check_it((select count(*) from schedule_swap_events)=(select n from before_events),'failed write does not add decision event');
drop trigger break_swap on employee_schedules;
create function pg_temp.break_swap_audit() returns trigger language plpgsql as $$begin raise exception 'JADWAL: Fiction injected audit failure';end$$;
create trigger break_swap_audit before insert on schedule_swap_events for each row execute function pg_temp.break_swap_audit();
set local role authenticated;
select pg_temp.deny(format('select hris_decide_schedule_swap(%L,true,%L)',(select id from schedule_swap_requests where status='Menunggu HR'),'Fiction audit failure'),'audit failure');
reset role;
select pg_temp.check_it(not exists(select to_jsonb(s) from employee_schedules s except select row from before_swap),'both cells rollback after audit fails');
select pg_temp.check_it((select count(*) from schedule_swap_requests where status='Menunggu HR')=1,'audit failure leaves request pending');
drop trigger break_swap_audit on schedule_swap_events;
